const deal = $('Deal Contract Sent Webhook').first().json;
const config = $('Get Config').first().json;
const body = deal.body && typeof deal.body === 'object' ? deal.body : deal;
const props = body.properties || body;

const valueFrom = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim()) {
      return String(value).trim();
    }
  }
  return '';
};

const money = (value) => {
  if (value === undefined || value === null || value === '') return 0;
  const normalized = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(normalized) ? normalized : 0;
};

const titleCase = (value) => value ? value.charAt(0).toUpperCase() + value.slice(1) : '';

const addressParts = [
  valueFrom(props.address, props.street, props.street_address, props.company_address),
  valueFrom(props.city, props.company_city),
  valueFrom(props.state, props.state_region, props.company_state),
  valueFrom(props.zip, props.zip_code, props.postal_code, props.company_zip),
  valueFrom(props.country, props.company_country)
].filter(Boolean);

const tierKey = valueFrom(props.tier).toLowerCase() || 'starter';
const tierInfo = (config.tiers && (config.tiers[tierKey] || config.tiers.starter)) || {
  name: titleCase(tierKey) || 'Starter',
  monthlyPrice: 0,
  setupFee: 0
};

const rawPainSources = [
  valueFrom(props.deal_pain_points),
  valueFrom(props.painPoints),
  valueFrom(props.pain_point_summary)
].filter(Boolean);

const uniquePainSources = [...new Set(rawPainSources)];
const painPoints = uniquePainSources.join('\n\n');
const contactFirstName = valueFrom(props.contact_firstname, props.firstName, props.firstname);
const contactLastName = valueFrom(props.contact_lastname, props.lastName, props.lastname);
const contactName = [contactFirstName, contactLastName].filter(Boolean).join(' ');

const companyName = valueFrom(
  props.company,
  props.company_name,
  props.business_name,
  props.dealname,
  props.name
);
const tierMonthly = money(tierInfo.monthlyPrice);
const upfrontDue = money(tierInfo.setupFee);

const parseLineItemsRaw = () => {
  const candidates = [
    body.lineItems,
    body.line_items,
    props.lineItems,
    props.line_items,
    props.hs_line_items,
  ];
  for (const c of candidates) {
    if (Array.isArray(c) && c.length) return c;
    if (typeof c === 'string' && c.trim().startsWith('[')) {
      try {
        const parsed = JSON.parse(c);
        if (Array.isArray(parsed) && parsed.length) return parsed;
      } catch (e) { /* ignore */ }
    }
  }
  return [];
};

const normalizeLineItems = (raw) => {
  return raw.map((x, i) => {
    if (!x || typeof x !== 'object') return null;
    const qty = Math.max(1, Number(x.quantity ?? x.qty ?? x.hs_quantity ?? 1) || 1);
    const unit = money(x.unitPrice ?? x.price ?? x.rate ?? x.hs_price ?? x.hs_unit_price);
    const lineTotal = money(x.amount ?? x.line_amount ?? x.total ?? x.line_total ?? x.hs_line_item_amount);
    const name = valueFrom(x.name, x.productName, x.title, x.hs_sku, `Line item ${i + 1}`);
    const sku = valueFrom(x.hs_sku, x.sku, '');
    const description = valueFrom(x.description, x.details, x.notes, '');
    let amount = lineTotal;
    if (!amount && unit) amount = unit * qty;
    if (!amount) amount = 0;
    return {
      name,
      sku,
      description,
      quantity: qty,
      unitPrice: unit || (qty ? amount / qty : amount),
      amount,
    };
  }).filter(Boolean);
};

const rawLineItems = parseLineItemsRaw();
const lineItems = normalizeLineItems(rawLineItems);
const lineItemsSubtotal = lineItems.reduce((s, li) => s + (Number(li.amount) || 0), 0);

const explicitDealAmount = money(props.amount);
const explicitDiscount = money(
  valueFrom(
    props.hs_total_discount,
    props.total_discount,
    props.deal_discount,
    props.discount_amount,
    props.hs_discount,
  ),
);
let impliedDiscount = 0;
if (
  explicitDiscount <= 0 &&
  lineItemsSubtotal > 0 &&
  explicitDealAmount > 0 &&
  lineItemsSubtotal > explicitDealAmount + 0.005
) {
  impliedDiscount = lineItemsSubtotal - explicitDealAmount;
}
const totalDiscount = explicitDiscount > 0 ? explicitDiscount : impliedDiscount;

const tierAmount =
  explicitDealAmount > 0
    ? explicitDealAmount
    : lineItemsSubtotal > 0
      ? lineItemsSubtotal
      : upfrontDue;
const dealAmountForDisplay = explicitDealAmount > 0 ? explicitDealAmount : tierAmount;
const remainingTierBalance = Math.max(tierAmount - upfrontDue, 0);
const launchBalance = remainingTierBalance + tierMonthly;

const productList = lineItems.map((i) => ({
  sku: i.sku || '',
  name: i.name || '',
  price: i.unitPrice ?? (i.quantity ? i.amount / i.quantity : i.amount),
}));

return [{
  json: {
    clientName: valueFrom(props.dealname, props.name, props.company, props.business_name, props.company_name),
    company: companyName,
    companyName,
    industry: valueFrom(props.industry),
    painPoints,
    painPointSummary: valueFrom(props.pain_point_summary, props.painPoints),
    rawPainPoints: valueFrom(props.deal_pain_points, painPoints),
    dealValue: tierAmount,
    dealAmount: dealAmountForDisplay,
    lineItemsSubtotal,
    totalDiscount,
    lineItems,
    tierAmount,
    tier: tierKey,
    tierLabel: tierInfo.name || titleCase(tierKey) || 'Starter',
    tierMonthly,
    upfrontDue,
    launchBalance,
    productList,
    dealId: valueFrom(body.id, deal.id, body.dealId, deal.dealId),
    contactEmail: valueFrom(props.contact_email, props.email),
    contactPhone: valueFrom(props.contact_phone, props.phone, props.mobilephone),
    contactFirstName,
    contactName: contactName || contactFirstName,
    address: addressParts.join(', '),
    driveFolderId: valueFrom(props.client_drive_folder_id),
    config
  }
}];

const d = $('Extract Deal Data').first().json;
return [{
  json: {
    message: `Contract Generation skipped: no client_drive_folder_id on deal for "${d.clientName}". Set the property or complete onboarding so the client Drive folder exists.`,
    priority: 'warning'
  }
}];

const d = $('Extract Deal Data').first().json;
const sc = [d.rawPainPoints, d.painPointSummary].filter(Boolean).join('\n') || d.painPoints || '(None provided)';
const pl =
  d.lineItems && d.lineItems.length > 0
    ? d.lineItems
        .map(
          (li, i) =>
            `  ${i + 1}. ${li.name || 'Item'}${li.sku ? ` [${li.sku}]` : ''} — Qty ${li.quantity ?? 1} @ $${Number(li.unitPrice || 0).toLocaleString()} — Line $${Number(li.amount || 0).toLocaleString()}${li.description ? ` (${li.description})` : ''}\n`,
        )
        .join('')
    : d.productList && d.productList.length > 0
      ? d.productList.map((p) => `  - ${p.name} (${p.sku}): $${Number(p.price).toLocaleString()}`).join('\n')
      : `  - Tier: ${d.tierLabel} — $${Number(d.tierAmount).toLocaleString()}`;

const pricingNotes = [
  (d.lineItemsSubtotal || 0) > 0 ? `Line items subtotal: $${Number(d.lineItemsSubtotal).toLocaleString()}` : null,
  (d.totalDiscount || 0) > 0 ? `Discounts: $${Number(d.totalDiscount).toLocaleString()}` : null,
].filter(Boolean).join(' · ');

const systemPrompt = `You are acting as an expert business and contract attorney specializing in New Jersey technology services law, drafting Exhibit A (Statement of Work) for a Master Services Agreement on behalf of IntraWeb Technologies LLC.

COMPANY PROFILE
Legal Name: IntraWeb Technologies LLC | New Jersey LLC
Principal: John Schibelli | jschibelli@gmail.com | intrawebtech.com

STANDARD TERMS
Payment: Net 15. Late fee: 1.5%/month (18%/yr).
Revisions: Starter/Website = 2 rounds included. Growth/Advanced = 3 rounds included. Additional rounds: $150-$175/hr after signed Change Order.
Governing Law: State of New Jersey. Venue: Morris County.

OUTPUT RULES
Return ONLY clean semantic HTML for the Exhibit A body. No markdown, no backticks, no DOCTYPE, no html/head/body tags.
Use only: h2, h3, p, ul, ol, li, strong.
Do not include signatures, governing law, liability caps, or payment terms — those are in the MSA wrapper.
Do not invent facts not in the payload. Use [CONFIRM WITH CLIENT] for missing data.`;

const userPrompt = `Generate Exhibit A — Statement of Work.

CLIENT: ${d.clientName} | ${d.company} | ${d.industry || 'industry not provided'} | ${d.contactEmail || 'email not provided'}

ENGAGEMENT
Tier: ${d.tierLabel}
Deal line items / products:
${pl}
HubSpot deal amount (after discounts): $${Number(d.dealAmount || d.tierAmount).toLocaleString()}${pricingNotes ? ` — ${pricingNotes}` : ''}
Tier payment template — Monthly: $${Number(d.tierMonthly).toLocaleString()} | Upfront: $${Number(d.upfrontDue).toLocaleString()}

DISCOVERY CONTEXT
"""
${sc}
"""

Sections: 1. Objectives 2. Deliverables and workstreams (reference SKUs) 3. Client responsibilities 4. Out of scope 5. Change request process (ref $150-$175/hr and Net 15)`;

return [{ json: { systemPrompt, userPrompt, maxTokens: 3500 } }];

const raw = $('Call Claude API').first().json;
const text = (raw.content && raw.content[0] && raw.content[0].text) ? raw.content[0].text : '';
const d = $('Extract Deal Data').first().json;
return [{ json: { data: { text }, html: text, fileName: `IntraWeb — ${d.clientName} — Master Services Agreement.pdf` } }];

const claudeResult = $('Parse Claude Response').first().json;
const d = $('Extract Deal Data').first().json;
const config = d.config || {};
const branding = config.branding || {};
const owner = (config && config.owner) || {};
const companyName = owner.companyName || 'IntraWeb Technologies LLC';
const ownerEmail = owner.email || '';
const ownerPhone = owner.phone || '';
const ownerName = owner.name || 'Authorized Representative';
const clientLegalName = d.company || d.clientName || 'Client';
const effectiveDate = new Date().toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});
const docId = d.dealId ? `MSA-${String(d.dealId).slice(0, 12)}` : `MSA-${Date.now().toString(36).toUpperCase()}`;

const exhibitBody =
  (claudeResult.data ? claudeResult.data.text : claudeResult.html || '').trim() ||
  '<p class="body-text">Exhibit A could not be generated.</p>';

const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const formatCurrency = (value) => {
  const numeric = Number(value || 0);
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(Number.isFinite(numeric) ? numeric : 0);
};

const lineItemsPdf = Array.isArray(d.lineItems) ? d.lineItems : [];
const subtotalPdf =
  Number(d.lineItemsSubtotal) ||
  lineItemsPdf.reduce((s, li) => s + (Number(li.amount) || 0), 0);
const discPdf = Math.max(0, Number(d.totalDiscount) || 0);
const dealAmtPdf = Number(d.dealAmount) || Number(d.tierAmount) || 0;
const finalDealPdf =
  dealAmtPdf > 0
    ? dealAmtPdf
    : subtotalPdf - discPdf > 0
      ? subtotalPdf - discPdf
      : subtotalPdf;

const feeTableBody = (() => {
  const rows = [];
  if (lineItemsPdf.length) {
    lineItemsPdf.forEach((li) => {
      const name = escapeHtml(li.name || 'Item');
      const sku =
        li.sku && String(li.sku).trim()
          ? ` <span class="muted">(${escapeHtml(li.sku)})</span>`
          : '';
      rows.push(
        `<tr><td>${name}${sku}<div class="line-table__meta">Qty ${escapeHtml(String(li.quantity ?? 1))} × ${escapeHtml(formatCurrency(li.unitPrice))}</div></td><td class="num">${escapeHtml(formatCurrency(li.amount))}</td></tr>`,
      );
    });
    rows.push(
      `<tr class="line-table__subtotal"><td>Subtotal (line items)</td><td class="num">${escapeHtml(formatCurrency(subtotalPdf))}</td></tr>`,
    );
    if (discPdf > 0.005) {
      rows.push(
        `<tr class="line-table__discount"><td>Discounts</td><td class="num">-${escapeHtml(formatCurrency(discPdf))}</td></tr>`,
      );
    }
    rows.push(
      `<tr class="line-table__total"><td><strong>Total deal amount</strong></td><td class="num"><strong>${escapeHtml(formatCurrency(finalDealPdf))}</strong></td></tr>`,
    );
  } else {
    rows.push(
      `<tr><td>Tier / package (${escapeHtml(d.tierLabel || d.tier || '')})</td><td class="num">${escapeHtml(formatCurrency(d.tierAmount))}</td></tr>`,
    );
    if (discPdf > 0.005) {
      rows.push(
        `<tr class="line-table__discount"><td>Discounts</td><td class="num">-${escapeHtml(formatCurrency(discPdf))}</td></tr>`,
      );
    }
    rows.push(
      `<tr class="line-table__total"><td><strong>Total deal amount</strong></td><td class="num"><strong>${escapeHtml(formatCurrency(finalDealPdf || d.tierAmount))}</strong></td></tr>`,
    );
  }
  rows.push(
    `<tr class="line-table__schedule"><td colspan="2">Payment timing estimates (tier template; invoice cadence per Provider)</td></tr>`,
  );
  rows.push(
    `<tr><td>Estimated upfront / setup</td><td class="num">${escapeHtml(formatCurrency(d.upfrontDue))}</td></tr>`,
  );
  rows.push(
    `<tr><td>Monthly recurring (if applicable)</td><td class="num">${escapeHtml(formatCurrency(d.tierMonthly))}</td></tr>`,
  );
  rows.push(
    `<tr><td>Launch / initial payment (estimate)</td><td class="num">${escapeHtml(formatCurrency(d.launchBalance))}</td></tr>`,
  );
  return rows.join('');
})();

const logoHtml = (() => {
  const b64 = branding.logoPdfBase64 || branding.logoDarkBase64;
  const url = branding.logoUrlDark || branding.logoUrl;
  if (b64 && String(b64).trim()) {
    const src = String(b64).startsWith('data:') ? b64 : `data:image/png;base64,${b64}`;
    return `<img class="doc-header__logo" src="${src}" alt="IntraWeb" height="36" />`;
  }
  if (url && String(url).trim()) {
    return `<img class="doc-header__logo" src="${escapeHtml(url)}" alt="IntraWeb" height="36" />`;
  }
  return `<div class="doc-header__wordmark" aria-hidden="true">IntraWeb</div>`;
})();

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Master Services Agreement — ${escapeHtml(clientLegalName)}</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap" rel="stylesheet" />
  <style>
    :root {
      --iw-slate-950: #0d1117;
      --iw-slate-900: #141b26;
      --iw-slate-800: #1c2636;
      --iw-slate-700: #253347;
      --iw-slate-600: #344659;
      --iw-slate-500: #4a6075;
      --iw-slate-400: #6b8399;
      --iw-slate-300: #96aebe;
      --iw-slate-200: #c4d1da;
      --iw-slate-100: #e4eaef;
      --iw-slate-50: #f2f5f8;
      --iw-teal: #00c2a8;
      --iw-teal-light: #00dfc8;
      --iw-teal-dim: #007a6a;
      --iw-teal-ghost: #e0f8f5;
      --iw-orange: #f26419;
      --iw-orange-dim: #c04e0e;
      --iw-orange-ghost: #fef0e8;
      --iw-white: #ffffff;
      --iw-off-white: #f8fafb;
      --iw-print-footer-block: 0.72in;
    }
    @page {
      size: letter;
      margin: 0.52in 0.58in 0.72in 0.58in;
    }
    * {
      box-sizing: border-box;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
    html,
    body {
      margin: 0;
      padding: 0;
      background: var(--iw-slate-50);
      color: var(--iw-slate-700);
      font-family: 'DM Sans', system-ui, sans-serif;
    }
    .iw-page {
      display: flex;
      flex-direction: column;
      width: 816px;
      max-width: 100%;
      min-height: 1056px;
      margin: 0 auto;
      background: var(--iw-slate-50);
      color: var(--iw-slate-700);
    }
    .iw-page > header,
    .iw-page > .doc-hero,
    .iw-page > .doc-meta-bar {
      flex-shrink: 0;
    }
    main.doc-body {
      flex: 1 1 auto;
    }
    @media print {
      .iw-page {
        display: block;
        width: 100%;
        min-height: 0;
        margin: 0;
      }
    }
    .doc-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 14px 24px;
      background: var(--iw-slate-950);
      border-bottom: 3px solid var(--iw-teal);
      color: var(--iw-white);
    }
    .doc-header__logo {
      height: 36px;
      width: auto;
      display: block;
    }
    .doc-header__wordmark {
      font-size: 18px;
      font-weight: 700;
      letter-spacing: 0.04em;
      color: var(--iw-white);
    }
    .doc-header__doc-type {
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--iw-slate-300);
    }
    .doc-header__doc-id {
      font-size: 10pt;
      font-weight: 600;
      color: var(--iw-white);
      margin-top: 4px;
      text-align: right;
    }
    .doc-hero {
      background: var(--iw-slate-900);
      padding: 32px 32px 28px;
      color: var(--iw-white);
      break-after: avoid-page;
      page-break-after: avoid;
    }
    .doc-hero__label {
      display: inline-block;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--iw-orange);
      margin-bottom: 10px;
    }
    .doc-hero__label::before {
      content: '— ';
      color: var(--iw-orange);
    }
    .doc-hero__title {
      margin: 0 0 10px;
      font-size: 24pt;
      font-weight: 700;
      line-height: 1.15;
      color: var(--iw-white);
    }
    .doc-hero__subtitle {
      margin: 0;
      max-width: 640px;
      font-size: 11pt;
      line-height: 1.55;
      color: var(--iw-slate-300);
    }
    .doc-meta-bar {
      display: flex;
      flex-wrap: wrap;
      background: var(--iw-slate-800);
      color: var(--iw-slate-100);
      font-size: 9.5pt;
    }
    .doc-meta-bar__item {
      flex: 1 1 0;
      min-width: 140px;
      padding: 12px 16px;
      border-right: 1px solid var(--iw-slate-600);
    }
    .doc-meta-bar__item:last-child {
      border-right: none;
    }
    .doc-meta-bar__k {
      font-size: 7.5pt;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--iw-slate-400);
      margin-bottom: 4px;
    }
    .doc-meta-bar__v {
      font-weight: 600;
      color: var(--iw-white);
      word-break: break-word;
    }
    .doc-body {
      background: var(--iw-white);
      padding: 44px 48px 56px;
    }
    @media print {
      .doc-body {
        padding-top: 36pt;
        padding-bottom: calc(36pt + var(--iw-print-footer-block));
      }
    }
    .doc-body > * + * {
      margin-top: 28px;
    }
    .doc-section__title {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 12pt;
      font-weight: 700;
      margin: 0 0 14px;
      padding-bottom: 8px;
      border-bottom: 1.5px solid var(--iw-slate-100);
      color: var(--iw-slate-800);
      break-after: avoid;
      page-break-after: avoid;
      break-inside: avoid;
    }
    section {
      break-inside: auto;
    }
    .doc-section__accent {
      width: 4px;
      height: 18px;
      background: var(--iw-teal);
      flex-shrink: 0;
    }
    .kv-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px 20px;
    }
    .kv-grid .kv-k {
      font-size: 7.5pt;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--iw-slate-400);
      margin-bottom: 4px;
    }
    .kv-grid .kv-v {
      font-size: 10pt;
      color: var(--iw-slate-800);
      font-weight: 600;
      word-break: break-word;
    }
    .party-box {
      border: 1px solid var(--iw-slate-100);
      border-radius: 10px;
      padding: 14px 16px;
      background: var(--iw-off-white);
    }
    .line-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 10pt;
      break-inside: auto;
    }
    .line-table thead {
      display: table-header-group;
    }
    .line-table tbody tr {
      break-inside: avoid;
      page-break-inside: avoid;
    }
    .line-table thead th {
      background: var(--iw-slate-950);
      color: var(--iw-white);
      text-align: left;
      padding: 10px 12px;
      font-weight: 700;
      font-size: 8.5pt;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }
    .line-table thead th:last-child {
      text-align: right;
    }
    .line-table tbody tr:nth-child(odd) {
      background: var(--iw-off-white);
    }
    .line-table tbody tr:nth-child(even) {
      background: var(--iw-white);
    }
    .line-table td {
      padding: 10px 12px;
      border-bottom: 1px solid var(--iw-slate-100);
      vertical-align: top;
    }
    .line-table td.num {
      text-align: right;
      font-weight: 700;
      color: var(--iw-slate-800);
      white-space: nowrap;
    }
    .line-table__meta {
      font-size: 8.5pt;
      color: var(--iw-slate-500);
      font-weight: 500;
      margin-top: 3px;
    }
    .line-table .muted {
      font-weight: 500;
      color: var(--iw-slate-500);
    }
    .line-table tr.line-table__subtotal td {
      background: var(--iw-off-white);
      font-weight: 700;
      border-bottom: 1px solid var(--iw-slate-200);
    }
    .line-table tr.line-table__discount td {
      color: var(--iw-orange-dim);
      font-weight: 700;
      background: var(--iw-orange-ghost);
    }
    .line-table tr.line-table__total td {
      background: var(--iw-teal-ghost);
      color: var(--iw-teal-dim);
      font-weight: 800;
      font-size: 11pt;
      border-bottom: none;
    }
